def pause_to_plus1_purine_to_pyrimidine(X):
    seq = X["raw_sequence"].fillna("").astype(str).str.upper()
    return (
        seq.str.len().ge(52)
        & seq.str[50].isin(["A", "G"])
        & seq.str[51].isin(["C", "T"])
    ).astype(int).rename("pause_to_plus1_purine_to_pyrimidine")

def upstream_minus26_to_minus17_GC_rich(X):
    seqs = X["raw_sequence"].astype(str).str.upper()
    return seqs.str.slice(24, 34).apply(lambda s: int(sum(nt in {"G", "C"} for nt in s) >= 7))

def upstream_minus25_to_minus16_AT_count(X):
    seqs = X["raw_sequence"].astype(str).str.upper().str.slice(25, 35)
    return seqs.str.count("A") + seqs.str.count("T")

def central_minus3_to_plus1_GC_rich(X):
    seq = X["raw_sequence"].fillna("").astype(str).str.upper()
    window = seq.str.slice(47, 52)
    gc_count = window.str.count(r"[GC]")
    return (gc_count >= 4).astype(int)

def upstream_minus10_to_minus1_AT_fraction(X):
    seqs = X["raw_sequence"].astype(str).str.upper()
    return seqs.str.slice(40, 50).apply(lambda s: sum(1 for c in s if c in {"A", "T"}) / 10.0).rename("upstream_minus10_to_minus1_AT_fraction")

def plus1_is_GC(X):
    seq = X["raw_sequence"].astype(str).str.upper()
    return seq.str[51].isin(["G", "C"]).astype(int).rename("plus1_is_GC")

def upstream_minus11_to_minus2_G_enriched(X):
    seqs = X["raw_sequence"].astype(str)
    return seqs.str.slice(39, 49).str.count("G").ge(4).astype(int).rename("upstream_minus11_to_minus2_G_enriched")

def minus1_and_pause_site_GC_count(X):
    seq = X["raw_sequence"].astype(str).str.upper()
    return seq.str[49].isin(["G", "C"]).astype(int) + seq.str[50].isin(["G", "C"]).astype(int)

def downstream_plus20_to_plus30_gc_count(X):
    seqs = X["raw_sequence"].astype(str).str.upper()
    return seqs.str.slice(70, 81).str.count(r"[GC]")
